  "camera.noDartsDetectedManual": { de: "Keine Darts erkannt · bitte manuell erfassen", en: "No darts detected · please enter manually", fr: "Aucune fléchette détectée · saisis manuellement", pl: "Nie wykryto lotek · wprowadź ręcznie", nl: "Geen darts gedetecteerd · voer handmatig in", tr: "Dart algılanmadı · lütfen manuel girin" },
  "camera.roundDetected": { de: "Runde erkannt:", en: "Round detected:", fr: "Manche détectée :", pl: "Wykryto rundę:", nl: "Ronde gedetecteerd:", tr: "Tur algılandı:" },
