  "tournament.randomDrawDesc": { de: "Die Paarungen der ersten Runde werden beim Start zufällig gelost.", en: "The first round's pairings are drawn randomly on start.", fr: "Les appariements du premier tour sont tirés au sort aléatoirement au démarrage.", pl: "Pary pierwszej rundy są losowane losowo przy starcie.", nl: "De koppelingen van de eerste ronde worden willekeurig geloot bij start.", tr: "İlk turun eşleşmeleri başlangıçta rastgele belirlenir." },
  "tournament.manualDrawDesc": { de: "Die Reihenfolge der Teilnehmerliste bestimmt die Paarungen: 1 vs 2, 3 vs 4, usw.", en: "The order of the participant list determines the pairings: 1 vs 2, 3 vs 4, etc.", fr: "L'ordre de la liste des participants détermine les appariements : 1 vs 2, 3 vs 4, etc.", pl: "Kolejność listy uczestników określa pary: 1 vs 2, 3 vs 4, itd.", nl: "De volgorde van de deelnemerslijst bepaalt de koppelingen: 1 vs 2, 3 vs 4, enz.", tr: "Katılımcı listesinin sırası eşleşmeleri belirler: 1 vs 2, 3 vs 4, vb." },
