  "tournament.scanForPublicLiveView": { de: "Scannen führt direkt zur öffentlichen Live-Ansicht — ohne Login oder Registrierung. Zum Ausdrucken oder Anzeigen am Eingang.", en: "Scanning leads directly to the public live view — no login or registration. For printing or displaying at the entrance.", fr: "Scanner mène directement à la vue en direct publique — sans connexion ni inscription. À imprimer ou afficher à l'entrée.", pl: "Skanowanie prowadzi bezpośrednio do publicznego widoku na żywo — bez logowania czy rejestracji. Do wydrukowania lub wyświetlenia przy wejściu.", nl: "Scannen leidt direct naar de openbare live-weergave — zonder inloggen of registratie. Om af te drukken of te tonen bij de ingang.", tr: "Tarama doğrudan herkese açık canlı görünüme götürür — giriş veya kayıt gerekmez. Girişte yazdırmak veya göstermek için." },
  "tournament.screenMode": { de: "Bildschirm-Modus", en: "Screen mode", fr: "Mode écran", pl: "Tryb ekranu", nl: "Schermmodus", tr: "Ekran modu" },
  "tournament.screenModeDesc": { de: "Startet direkt im automatischen Wechsel zwischen Turnierbaum/Liste und Board-Übersicht (alle 15s) — ideal für einen TV oder Beamer, den niemand mehr bedient.", en: "Starts directly in automatic rotation between bracket/list and board overview (every 15s) — ideal for a TV or projector nobody operates.", fr: "Démarre directement en rotation automatique entre tableau/liste et aperçu des cibles (toutes les 15s) — idéal pour une TV ou un projecteur que personne n'exploite.", pl: "Uruchamia się bezpośrednio w automatycznej rotacji między drabinką/listą a przeglądem tarcz (co 15s) — idealne dla telewizora lub projektora, którym nikt nie obsługuje.", nl: "Start direct in automatische wisseling tussen schema/lijst en bordoverzicht (elke 15s) — ideaal voor een tv of beamer die niemand bedient.", tr: "Doğrudan tablo/liste ve tahta genel görünümü arasında otomatik geçişle başlar (her 15 saniyede) — kimsenin çalıştırmadığı bir TV veya projeksiyon için idealdir." },
  "tournament.unattendedScreenTooltip": { de: "Für einen unbeaufsichtigten Bildschirm: automatischer Wechsel zwischen Turnierbaum und Board-Übersicht", en: "For an unattended screen: automatic rotation between bracket and board overview", fr: "Pour un écran non surveillé : rotation automatique entre le tableau et l'aperçu des cibles", pl: "Dla ekranu bez obsługi: automatyczna rotacja między drabinką a przeglądem tarcz", nl: "Voor een onbemand scherm: automatische wisseling tussen schema en bordoverzicht", tr: "Gözetimsiz bir ekran için: tablo ve tahta genel görünümü arasında otomatik geçiş" },
  "tournament.championSuffix": { de: "Champion!", en: "Champion!", fr: "Champion !", pl: "Mistrz!", nl: "Kampioen!", tr: "Şampiyon!" },
