  "tournament.scheduleAndScorekeeper": { de: "Spielplan & Schreiber", en: "Schedule & scorekeeper", fr: "Calendrier & marqueur", pl: "Harmonogram i sekretarz", nl: "Speelschema & scorekeeper", tr: "Program ve skorer" },
  "tournament.redrawScorekeepers": { de: "Schreiber neu auslosen", en: "Redraw scorekeepers", fr: "Retirer les marqueurs au sort", pl: "Wylosuj ponownie sekretarzy", nl: "Scorekeepers opnieuw loten", tr: "Skorerleri yeniden belirle" },
  "tournament.allPlayableMatchesDone": { de: "Alle aktuell spielbaren Partien sind erledigt.", en: "All currently playable matches are done.", fr: "Tous les matchs actuellement jouables sont terminés.", pl: "Wszystkie obecnie rozgrywalne mecze zostały zakończone.", nl: "Alle momenteel speelbare wedstrijden zijn afgerond.", tr: "Şu anda oynanabilir tüm maçlar tamamlandı." },
  "tournament.nowOnBoard": { de: "Jetzt am Board", en: "Now on the board", fr: "Maintenant sur la cible", pl: "Teraz na tarczy", nl: "Nu op het bord", tr: "Şimdi tahtada" },
  "tournament.playRound": { de: "Spielrunde", en: "Play round", fr: "Manche de jeu", pl: "Runda gry", nl: "Speelronde", tr: "Oyun turu" },
  "tournament.automaticTournamentRule": { de: "Automatisch (Turnier-Regel)", en: "Automatic (tournament rule)", fr: "Automatique (règle du tournoi)", pl: "Automatycznie (reguła turnieju)", nl: "Automatisch (toernooiregel)", tr: "Otomatik (turnuva kuralı)" },
  "tournament.autoScorekeeperExplain": { de: "„Automatisch“ = Schreiber wird vom Turnierplan vergeben: bevorzugt bereits ausgeschiedene Spieler, sonst der Verlierer des vorherigen Spiels am selben Board; in der ersten Runde ein Spieler, der erst später dran ist.", en: "\"Automatic\" = the scorekeeper is assigned by the tournament plan: preferring already-eliminated players, otherwise the loser of the previous match on the same board; in round 1, a player who isn't up yet.", fr: "« Automatique » = le marqueur est attribué par le plan du tournoi : de préférence des joueurs déjà éliminés, sinon le perdant du match précédent sur la même cible ; au premier tour, un joueur qui n'est pas encore de service.", pl: "„Automatycznie” = sekretarz jest przydzielany przez plan turnieju: preferowani są już wyeliminowani gracze, w przeciwnym razie przegrany z poprzedniego meczu na tej samej tarczy; w pierwszej rundzie gracz, który jeszcze nie gra.", nl: "\"Automatisch\" = de scorekeeper wordt toegewezen door het toernooiplan: bij voorkeur al uitgeschakelde spelers, anders de verliezer van de vorige wedstrijd op hetzelfde bord; in ronde 1 een speler die nog niet aan de beurt is.", tr: "\"Otomatik\" = skorer turnuva planına göre atanır: önce elenmiş oyuncular tercih edilir, aksi halde aynı tahtadaki önceki maçın kaybedeni; 1. turda ise henüz sırası gelmemiş bir oyuncu." },
  "tournament.manageParticipants": { de: "Teilnehmer verwalten", en: "Manage participants", fr: "Gérer les participants", pl: "Zarządzaj uczestnikami", nl: "Deelnemers beheren", tr: "Katılımcıları yönet" },
  "tournament.withdrawHint": { de: "Spieler, die nicht erscheinen oder aufgeben, hier zurückziehen – Baum, Spielplan und Schreiber werden neu berechnet.", en: "Withdraw players who don't show up or give up here — bracket, schedule, and scorekeepers get recalculated.", fr: "Retire ici les joueurs qui ne se présentent pas ou abandonnent — le tableau, le calendrier et les marqueurs sont recalculés.", pl: "Wycofaj tutaj graczy, którzy się nie stawią lub poddadzą — drabinka, harmonogram i sekretarze zostaną przeliczone.", nl: "Trek hier spelers terug die niet komen opdagen of opgeven — schema, speelschema en scorekeepers worden herberekend.", tr: "Gelmeyen veya vazgeçen oyuncuları buradan çekin — tablo, program ve skorerler yeniden hesaplanır." },
  "tournament.withdrawConfirmSuffix": { de: "zurückziehen?", en: "withdraw?", fr: "retirer ?", pl: "wycofać?", nl: "terugtrekken?", tr: "çekilsin mi?" },
  "tournament.withdrawWarning": { de: "werden als Aufgabe gewertet, Baum, Spielplan und Schreiber neu berechnet. Bereits gespielte Ergebnisse bleiben erhalten.", en: "will be scored as a forfeit, and the bracket, schedule, and scorekeepers will be recalculated. Results already played stay as they are.", fr: "seront comptabilisés comme forfait, et le tableau, le calendrier et les marqueurs seront recalculés. Les résultats déjà joués restent inchangés.", pl: "zostaną zaliczone jako walkower, a drabinka, harmonogram i sekretarze zostaną przeliczone. Już rozegrane wyniki pozostają bez zmian.", nl: "worden geteld als opgave, en schema, speelschema en scorekeepers worden herberekend. Reeds gespeelde resultaten blijven ongewijzigd.", tr: "hükmen mağlubiyet olarak sayılacak, tablo, program ve skorerler yeniden hesaplanacak. Zaten oynanmış sonuçlar olduğu gibi kalır." },
  "tournament.allOpenMatchesFrom": { de: "Alle noch offenen Matches von", en: "All still-open matches from", fr: "Tous les matchs encore ouverts de", pl: "Wszystkie jeszcze otwarte mecze", nl: "Alle nog openstaande wedstrijden van", tr: "Şu kişinin hâlâ açık olan tüm maçları:" },
  "tournament.withdrawCapital": { de: "Zurückziehen", en: "Withdraw", fr: "Retirer", pl: "Wycofaj", nl: "Terugtrekken", tr: "Çekil" },
  "tournament.editMatchHeading": { de: "Partie bearbeiten", en: "Edit match", fr: "Modifier le match", pl: "Edytuj mecz", nl: "Wedstrijd bewerken", tr: "Maçı düzenle" },
  "tournament.emptyMeansBye": { de: "Leer lassen = Freilos (BYE). Ergebnisse dieser Partie werden zurückgesetzt.", en: "Leave empty = bye (BYE). Results of this match will be reset.", fr: "Laisser vide = exempt (BYE). Les résultats de ce match seront réinitialisés.", pl: "Pozostaw puste = wolny los (BYE). Wyniki tego meczu zostaną zresetowane.", nl: "Leeg laten = vrijlot (BYE). Resultaten van deze wedstrijd worden gereset.", tr: "Boş bırak = bay (BYE). Bu maçın sonuçları sıfırlanacak." },
  "tournament.player1ByePlaceholder": { de: "Spieler 1 (leer = BYE)", en: "Player 1 (empty = BYE)", fr: "Joueur 1 (vide = BYE)", pl: "Gracz 1 (puste = BYE)", nl: "Speler 1 (leeg = BYE)", tr: "Oyuncu 1 (boş = BYE)" },
  "tournament.player2ByePlaceholder": { de: "Spieler 2 (leer = BYE)", en: "Player 2 (empty = BYE)", fr: "Joueur 2 (vide = BYE)", pl: "Gracz 2 (puste = BYE)", nl: "Speler 2 (leeg = BYE)", tr: "Oyuncu 2 (boş = BYE)" },
  "tournament.editModeForRound": { de: "Modus für Runde", en: "Mode for round", fr: "Mode pour le tour", pl: "Tryb dla rundy", nl: "Modus voor ronde", tr: "Tur için mod" },
